service.method:

SELECT COUNT(*) AS CNT FROM SSIAD
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER = ${SMR_NUMBER}


SELECT
	  SUBJECT 						AS SUBJECT
	, SUBMISSION_PLACE 				AS SUBMISSION_PLACE
	, EXPLANATION 					AS EXPLANATION
FROM SSIAD  
WHERE HOUSE_CODE 	= ${session.HOUSE_CODE}
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND SMR_NUMBER 	= ${SMR_NUMBER}
ORDER BY SMR_NUMBER DESC


UPDATE SGWGL
   SET SUX_WKEY4 = ${IAMS_DOC_NO}
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE 	= ${session.COMPANY_CODE}
   AND APP_NO = ${APP_NO}
   AND APP_NO_SEQ = ${APP_NO_SEQ}


		UPDATE SSETL
		   SET SMR_STATUS = ${SMR_STATUS}
  		     , REJECT_REMARK = ${APPR_COMMENT}
  		     , CONFIRM_USER_ID = ${APPR_USER_ID}
  		     , CONFIRM_DATE = ${ACCEPT_DATE}
  		     , CONFIRM_TIME = ${ACCEPT_TIME}
		 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
		   AND COMPANY_CODE = ${session.COMPANY_CODE}
		   AND SMR_NUMBER 	= ${SMR_NUMBER}


	SELECT 
		ATTACH_NO
	FROM SSEDC 
	WHERE HOUSE_CODE = ${session.HOUSE_CODE}
      AND COMPANY_CODE = ${session.COMPANY_CODE}
      AND SMR_NUMBER = ${SMR_NUMBER}


		UPDATE SSIAD
		   SET SMR_STATUS = ${SMR_STATUS}
  		     , REJECT_REASON = ${APPR_COMMENT}
  		     , CONFIRM_USER_ID = ${APPR_USER_ID}
  		     , CONFIRM_DATE = ${ACCEPT_DATE}
  		     , CONFIRM_TIME = ${ACCEPT_TIME}
		 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
		   AND COMPANY_CODE = ${session.COMPANY_CODE}
		   AND SMR_NUMBER 	= ${SMR_NUMBER}


SELECT CONCAT(APPLY_TYPE, 'S') AS APPLY_FOR
     , RE_FLAG
  FROM SSIAD
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


SELECT CONCAT(APPLY_TYPE, 'S') AS APPLY_FOR
  FROM SSETL
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SMR_NUMBER 	= ${SMR_NUMBER}


INSERT INTO SAPPP (
       HOUSE_CODE
     , COMPANY_CODE
     , SMR_NUMBER
     , SEQ
     , RECENT
     , APP_STATUS
     , APPLY_FOR
     , POSTPROCESSED
     , ADD_DATE
     , ADD_TIME
     , CONFIRM_USER_ID
     , APP_COMMENT
     , APP_NO
     , APP_NO_SEQ
     , APP_LINE_SEQ
     , RE_FLAG
) VALUES(
       ${session.HOUSE_CODE}
     , ${session.COMPANY_CODE}
     , ${SMR_NUMBER}
     , CAST((CAST(NVL(
     			(SELECT PP.SEQ
				  FROM SAPPP PP
		 		 WHERE PP.HOUSE_CODE = ${session.HOUSE_CODE}
		   		   AND PP.COMPANY_CODE = ${session.COMPANY_CODE}
		   		   AND PP.SMR_NUMBER = ${SMR_NUMBER})
       , '0') as number(5)) + 1) as varchar2(5))
     , 'Y'
     , ${SMR_STATUS}
     , ${APPLY_FOR}
     , 'N'
     , ${ACCEPT_DATE}
     , ${ACCEPT_TIME}
     , ${APPR_USER_ID}
     , ${APPR_COMMENT}
     , ${APP_NO}
     , ${APP_NO_SEQ}
     , ${APP_LINE_SEQ}
     , ${RE_FLAG}
)


UPDATE SSEDC_SEAL SET
	COMPLETE_FLAG	= ${COMPLETE_FLAG}
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}


	    INSERT INTO SPMGT (
			HOUSE_CODE
			,COMPANY_CODE
			,CONT_NO
			,CONT_GL_SEQ
			,SEQ
			,ADD_DATE
			,ADD_TIME
			,USER_COMPANY_CODE
			,USER_ID
			,ACTION
			,IP
	    ) VALUES (
            ${session.HOUSE_CODE}
            ,${session.COMPANY_CODE}
            ,${SMR_NUMBER}
            ,'1'
            ,(SELECT COUNT(1) + 1
                  FROM SPMGT InPMGT
                 WHERE InPMGT.HOUSE_CODE   = ${session.HOUSE_CODE}
                   AND InPMGT.COMPANY_CODE = ${session.COMPANY_CODE}
                   AND InPMGT.CONT_NO      = ${SMR_NUMBER}
                   AND InPMGT.CONT_GL_SEQ  = '1'
               )
			,${current.DATE}
			,${current.TIME}
			,${session.COMPANY_CODE}
			,${session.ID}
			,${ACTION}
			,${IP}
	    )


		UPDATE 
			SQNAQ
		SET 
			STATUS 				= ${STATUS}
			,CHANGE_DATE		= ${ACCEPT_DATE}
  		    ,CHANGE_TIME 		= ${ACCEPT_TIME}
		WHERE 
			HOUSE_CODE 			= ${session.HOUSE_CODE} 
			AND COMPANY_CODE 	= ${session.COMPANY_CODE}
			AND QNA_NUMBER 		= ${QNA_NUMBER}


SELECT
	*
FROM
	SQNAQ
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND QNA_NUMBER = ${QNA_NUMBER}
